template:
[EMC]
# Name of the machine (used for display and logging)
MACHINE = {{ machine_name }}

# Debug level (0 = none, 99 = very verbose)
DEBUG = {{ emc_debug_level }}

[DISPLAY]
# GUI application to use (e.g., AXIS, TK, QTVCP)
DISPLAY = {{ display_type }}

# Path to the main UI file (if applicable, e.g., for QTVCP)
{% if display_ui_path %}# UI file path
UI = {{ display_ui_path }}{% endif %}

# Cycle time (ms) for GUI updates
CYCLE_TIME = {{ display_cycle_time }}

# Maximum feed override (as fraction, e.g. 1.5 = 150%)
MAX_FEED_OVERRIDE = {{ max_feed_override }}

# Minimum spindle override (as fraction, e.g. 0.5 = 50%)
MIN_SPINDLE_OVERRIDE = {{ min_spindle_override }}

# Maximum spindle override (as fraction, e.g. 2.0 = 200%)
MAX_SPINDLE_OVERRIDE = {{ max_spindle_override }}

# Position feedback source: ACTUAL (default) or COMMANDED
POSITION_OFFSET = {{ position_offset }}

# Position feedback mode: RELATIVE (default) or MACHINE
POSITION_FEEDBACK = {{ position_feedback }}

# Default linear units: MM or INCHES
DEFAULT_LINEAR_UNITS = {{ default_linear_units }}

# Angular units: DEGREES or RADIANS
DEFAULT_ANGULAR_UNITS = {{ default_angular_units }}

[RS274NGC]
# Path to the HAL configuration (HAL file to load before RT motion)
HALFILE = {{ halfile_path }}

# Optional: additional HAL files (comma-separated list)
{% if halfile_extra %}# Extra HAL files
HALFILE = {{ halfile_extra | join(', ') }}{% endif %}

# Path to the startup G-code file (runs after HAL load)
{% if startup_gcode_path %}# Startup G-code
RUN_INI = {{ startup_gcode_path }}{% endif %}

# Subroutine path (for user-defined G-codes)
SUBROUTINE_PATH = {{ subroutine_path }}

# Error log level: LOG, WARN, ERROR
ERROR_LOG_LEVEL = {{ error_log_level }}

[EMCMOT]
# Communications manager (e.g., "emcmotc" or "emcmotp")
EMCMOT = {{ emcmot_module }}

# Timeout (sec) for communications with motion controller
COMM_TIMEOUT = {{ emcmot_comm_timeout }}

# Wait time (sec) for initial heartbeat
COMM_WAIT = {{ emcmot_comm_wait }}

# Base task period (sec); typically 1ms (0.001) for real-time
BASE_PERIOD = {{ base_period }}

# Servo task period (sec); typically 1ms (0.001) for real-time
SERVO_PERIOD = {{ servo_period }}

[HAL]
# HAL configuration files to load at startup
{% for halfile in hal_files %}
# Load HAL component: {{ halfile.name }}
{% if halfile.load_before_motion %}# Loaded before motion controller
{% endif %}HALCMD = [HAL] loadusr -W {{ halfile.path }}{% endfor %}

[HALUI]
# List of HAL UI components to load (e.g., for custom LCD or LED displays)
{% if halui_modules %}# HAL UI modules to load
{% for mod in halui_modules %}HALCMD = [HALUI] loadusr -W {{ mod }}{% endfor %}{% endif %}

[TRAJ]
# Maximum number of axes supported (including spindles as virtual axes)
AXES = {{ traj_axes }}

# Maximum linear velocity (in configured units per second)
MAX_LINEAR_VELOCITY = {{ traj_max_linear_velocity }}

# Default linear acceleration (units/sec²)
DEFAULT_LINEAR_ACCEL = {{ traj_default_linear_accel }}

# Maximum linear acceleration (units/sec²)
MAX_LINEAR_ACCEL = {{ traj_max_linear_accel }}

# Maximum angular velocity (e.g., for rotary axes)
MAX_ANGULAR_VELOCITY = {{ traj_max_angular_velocity }}

[AXIS_0]
# Axis configuration (X-axis typical)
TYPE = {{ axis_0.type }}
MAX_VELOCITY = {{ axis_0.max_velocity }}
MAX_ACCELERATION = {{ axis_0.max_acceleration }}
BACKLASH = {{ axis_0.backlash }}
INPUT_SCALE = {{ axis_0.input_scale }}
OUTPUT_SCALE = {{ axis_0.output_scale }}
MIN_LIMIT = {{ axis_0.min_limit }}
MAX_LIMIT = {{ axis_0.max_limit }}
HOME = {{ axis_0.home }}
HOME_OFFSET = {{ axis_0.home_offset }}
HOME_SEARCH_VEL = {{ axis_0.home_search_vel }}
HOME_LATCH_VEL = {{ axis_0.home_latch_vel }}

{% if axis_1 %}[AXIS_1]
TYPE = {{ axis_1.type }}
MAX_VELOCITY = {{ axis_1.max_velocity }}
MAX_ACCELERATION = {{ axis_1.max_acceleration }}
BACKLASH = {{ axis_1.backlash }}
INPUT_SCALE = {{ axis_1.input_scale }}
OUTPUT_SCALE = {{ axis_1.output_scale }}
MIN_LIMIT = {{ axis_1.min_limit }}
MAX_LIMIT = {{ axis_1.max_limit }}
HOME = {{ axis_1.home }}
HOME_OFFSET = {{ axis_1.home_offset }}
HOME_SEARCH_VEL = {{ axis_1.home_search_vel }}
HOME_LATCH_VEL = {{ axis_1.home_latch_vel }}
{% endif %}

{% if axis_2 %}[AXIS_2]
TYPE = {{ axis_2.type }}
MAX_VELOCITY = {{ axis_2.max_velocity }}
MAX_ACCELERATION = {{ axis_2.max_acceleration }}
BACKLASH = {{ axis_2.backlash }}
INPUT_SCALE = {{ axis_2.input_scale }}
OUTPUT_SCALE = {{ axis_2.output_scale }}
MIN_LIMIT = {{ axis_2.min_limit }}
MAX_LIMIT = {{ axis_2.max_limit }}
