HOME_OFFSET = {{ axis_2.home_offset }}
HOME_SEARCH_VEL = {{ axis_2.home_search_vel }}
HOME_LATCH_VEL = {{ axis_2.home_latch_vel }}
{% endif %}

{% if axis_3 %}[AXIS_3]
TYPE = {{ axis_3.type }}
MAX_VELOCITY = {{ axis_3.max_velocity }}
MAX_ACCELERATION = {{ axis_3.max_acceleration }}
BACKLASH = {{ axis_3.backlash }}
INPUT_SCALE = {{ axis_3.input_scale }}
OUTPUT_SCALE = {{ axis_3.output_scale }}
MIN_LIMIT = {{ axis_3.min_limit }}
MAX_LIMIT = {{ axis_3.max_limit }}
HOME = {{ axis_3.home }}
HOME_OFFSET = {{ axis_3.home_offset }}
HOME_SEARCH_VEL = {{ axis_3.home_search_vel }}
