{% endif %}

[SPINDLE_0]
# Spindle configuration (e.g., for CNC mill or lathe)
MAX_SPEED = {{ spindle_0.max_speed }}
MIN_SPEED = {{ spindle_0.min_speed }}
TYPE = {{ spindle_0.type }}
PID_P = {{ spindle_0.pid_p }}
PID_I = {{ spindle_0.pid_i }}
